WATER_FIELDS = ["water_fill_id", "water_portion", "water_amount"]
FOOD_FIELDS = ["fill_id", "portion", "amount", "product_id"]


def forwards(apps, schema_editor):
    """Food and water become their own entries (PUP-216): a meal with both is split in two, the water one a copy
    with only the water side. Treats and Other become Dry food (never asked for, PUP-210). Each food gets the unit
    it shows in: a can in g (oz), a bag in kg (lb)."""
    Meal, Product = apps.get_model("pets", "Meal"), apps.get_model("pets", "Product")
    for meal in Meal.objects.all().iterator():
        has_water = meal.water or any(getattr(meal, f) is not None for f in WATER_FIELDS)
        has_food = meal.food or any(getattr(meal, f) is not None for f in FOOD_FIELDS)
        if has_water and not has_food:
            Meal.objects.filter(pk=meal.pk).update(kind="water", food=False)
        elif has_water:
            water = Meal.objects.get(pk=meal.pk)
            water.pk = None
            water.kind, water.food, water.notes = "water", False, ""  # the note stays on the food entry
            for f in FOOD_FIELDS:
                setattr(water, f, None)
            water.save()
            Meal.objects.filter(pk=meal.pk).update(water=False, **{f: None for f in WATER_FIELDS})
    Product.objects.exclude(category__in=["dry_food", "wet_food", "litter"]).update(category="dry_food")
    for product in Product.objects.select_related("household"):
        imperial = product.household.units == "imperial"
        small = product.category == "wet_food"
        product.unit = ("oz" if small else "lb") if imperial else ("g" if small else "kg")
        product.save(update_fields=["unit"])


